// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.memory.implimport com.roshan.persona.brain.context.SessionIdimport com.roshan.persona.brain.intent.Intentimport com.roshan.persona.brain.rule.storage.ConversationStateDataimport com.roshan.persona.brain.rule.storage.ConversationStateStorageimport com.roshan.persona.brain.skill.ConversationStageimport com.roshan.persona.brain.skill.SkillOutputimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport com.roshan.persona.database.dao.ConversationStateDaoimport com.roshan.persona.database.entity.ConversationStateEntityimport timber.log.Timberimport java.time.Instantimport com.roshan.persona.common.AppError/** * NOUS — Room Conversation State Storage (Crash-Safe). * * Implements [ConversationStateStorage] (defined in Brain Module 2) * using Room. Persists conversation state when a skill pauses for * input (NeedsInput). Survives app crashes and device reboots. * * State machine: *   PROCESSING → NEEDS_INPUT → (user input) → RESUMING → PROCESSING → SUCCESS * * TTL: 5 minutes — after which state is marked EXPIRED. * * @see <a href="docs/strategy/module-3-strategy-v2.md">§12 Brain Integration — StateManager</a> */class RoomConversationStateStorage(    private val dao: ConversationStateDao,) : ConversationStateStorage {    override suspend fun save(state: ConversationStateData): Result<Unit> {        return try {            val entity = ConversationStateEntity(                sessionId = state.sessionId.value,                correlationId = state.correlationId.value,                skillId = state.skillId,                intent = state.intent::class.simpleName ?: "Unknown", // simplified serialization                stage = state.stage.name,                partialOutput = null, // simplified — production would serialize SkillOutput                createdAt = state.createdAt.toEpochMilli(),                expiresAt = state.expiresAt.toEpochMilli(),            )            dao.upsert(entity)            Result.Success(Unit, state.correlationId, 0)        } catch (e: Exception) {            Timber.e(e, "Failed to save conversation state")            Result.Failure(AppError.from(e), CorrelationId.generate(), 0)        }    }    override suspend fun getActive(sessionId: SessionId): Result<ConversationStateData?> {        return try {            val now = System.currentTimeMillis()            val entity = dao.getActiveForSession(sessionId.value, now)            if (entity == null) {                return Result.Success(null, CorrelationId.generate(), 0)            }            if (entity.isExpired(now)) {                dao.deleteForSession(sessionId.value)                return Result.Success(null, CorrelationId.generate(), 0)            }            // Reconstruct state (simplified — production would deserialize Intent + SkillOutput)            val state = ConversationStateData(                sessionId = sessionId,                correlationId = CorrelationId(entity.correlationId),                skillId = entity.skillId,                intent = Intent.Unknown(raw = ""), // simplified                stage = runCatching { ConversationStage.valueOf(entity.stage) }                    .getOrDefault(ConversationStage.NEEDS_INPUT),                partialOutput = null,                createdAt = Instant.ofEpochMilli(entity.createdAt),                expiresAt = Instant.ofEpochMilli(entity.expiresAt),            )            Result.Success(state, state.correlationId, 0)        } catch (e: Exception) {            Timber.e(e, "Failed to get active conversation state")            Result.Failure(AppError.from(e), CorrelationId.generate(), 0)        }    }    override suspend fun markCompleted(sessionId: SessionId): Result<Unit> {        return try {            dao.deleteForSession(sessionId.value)            Result.Success(Unit, CorrelationId.generate(), 0)        } catch (e: Exception) {            Result.Failure(AppError.from(e), CorrelationId.generate(), 0)        }    }    override suspend fun markExpired(sessionId: SessionId): Result<Unit> {        return try {            dao.deleteForSession(sessionId.value)            Result.Success(Unit, CorrelationId.generate(), 0)        } catch (e: Exception) {            Result.Failure(AppError.from(e), CorrelationId.generate(), 0)        }    }    override suspend fun deleteAllForSession(sessionId: SessionId): Result<Unit> {        return try {            dao.deleteForSession(sessionId.value)            Result.Success(Unit, CorrelationId.generate(), 0)        } catch (e: Exception) {            Result.Failure(AppError.from(e), CorrelationId.generate(), 0)        }    }    override suspend fun deleteExpired(): Result<Int> {        return try {            val count = dao.deleteExpired(System.currentTimeMillis())            Result.Success(count, CorrelationId.generate(), 0)        } catch (e: Exception) {            Result.Failure(AppError.from(e), CorrelationId.generate(), 0)        }    }}